query:
mutation AddAwsAccount($accountId: String!, $accessKeyId: String!, $secretAccessKey: String!, $enabled: Boolean, $schedule: String!, $applications: [Int!]) {
  addAwsAccount(
    accountId: $accountId
    accessKeyId: $accessKeyId
    secretAccessKey: $secretAccessKey
    enabled: $enabled
    schedule: $schedule
    applications: $applications
  ) {
    status
    msg
    __typename
  }
}
